import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        int[][] all = Arrays.copyOf(intervals, intervals.length + 1);
        all[intervals.length] = newInterval;
        Arrays.sort(all, (first, second) -> Integer.compare(first[0], second[0]));
        List<int[]> result = new ArrayList<>();
        for (int[] interval : all) {
            if (result.isEmpty() || result.get(result.size() - 1)[1] < interval[0]) {
                result.add(new int[] {interval[0], interval[1]});
            } else {
                int[] last = result.get(result.size() - 1);
                last[1] = Math.max(last[1], interval[1]);
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

